"""No affiliate URL ever has to be generated by Mistral."""
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'superdeal_phase2_full'))

import pytest

from affiliate_link_ids import link_map, llm_input, restore_affiliate_urls
from backend import Backend

URL1 = 'https://other-affiliate.example/a?code=XY%2F9&ref=1'
URL2 = 'https://fkrt.cc/abcXYZ?offer=2'
URL3 = 'https://merchant-multi.test/deal?x=3'


def product(ids, name='Product'):
    return {
        'product_name': name, 'brand': None, 'ecommerce_platform': None,
        'deal_price': 99, 'original_price': None, 'discount_percentage': None,
        'link_ids': ids, 'confidence': 85, 'issues': [],
    }


def output(products, leftovers=None):
    return {
        'products': products, 'unassigned_link_ids': leftovers or [],
        'message_issues': [], 'analysis_summary': '',
    }


def test_arbitrary_domains_are_replaced_before_mistral():
    msg = f'Offer {URL1}, another {URL2}! More: {URL3}'
    context = llm_input(msg, {
        URL1: {'product_name': 'Phone', 'price': 99},
        URL3: {'mrp': 180},
    })
    assert URL1 not in context and URL2 not in context and URL3 not in context
    assert 'LINK_001' in context and 'LINK_002' in context and 'LINK_003' in context
    assert '!' in context and ',' in context


def test_multiple_products_exact_urls_roundtrip():
    msg = f'First {URL1} second {URL2}'
    mapping = link_map(msg)
    ids = list(mapping)
    model = output([product([ids[0]], 'A'), product([ids[1]], 'B')])
    result = restore_affiliate_urls(json.dumps(model), msg)
    validated = Backend.validate(result, msg)
    assert {url for p in validated['products'] for url in p['affiliate_urls']} == {URL1, URL2}
    assert all('link_ids' not in p for p in validated['products'])


def test_same_product_with_multiple_links():
    msg = f'{URL1} {URL2}'
    ids = list(link_map(msg))
    result = restore_affiliate_urls(output([product(ids)]), msg)
    assert set(result['products'][0]['affiliate_urls']) == {URL1, URL2}
    assert Backend.validate(result, msg)


@pytest.mark.parametrize('ids', [
    ['LINK_999'], ['LINK_001', 'LINK_001'], [],
])
def test_invalid_product_ids_fail_closed(ids):
    msg = f'Product {URL1}'
    with pytest.raises(ValueError):
        restore_affiliate_urls(output([product(ids)]), msg)


def test_missing_or_unassigned_links_block_publication():
    msg = f'{URL1} {URL2}'
    ids = list(link_map(msg))
    with pytest.raises(ValueError, match='Missing, invented, or duplicated link IDs'):
        restore_affiliate_urls(output([product([ids[0]])]), msg)
    restored = restore_affiliate_urls(output([product([ids[0]])], [ids[1]]), msg)
    with pytest.raises(ValueError, match='Unassigned URLs'):
        Backend.validate(restored, msg)


def test_no_silent_url_repair_and_no_extra_fields():
    msg = f'{URL1}'
    with pytest.raises(ValueError, match='Invalid link-ID product schema'):
        restore_affiliate_urls(output([dict(product(['LINK_001']), affiliate_urls=[URL1])]), msg)


def test_model_may_omit_summary_only():
    msg = f'{URL1}'
    model = output([product(['LINK_001'])])
    del model['analysis_summary']
    assert Backend.validate(restore_affiliate_urls(model, msg), msg)['analysis_summary'] == ''
